import{_ as t,a0 as p,w as o,s as r,I as i,x as n,a1 as l,A as e,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"用 rcm 管理隐藏文件 | LCTT x X-CMD","titleTemplate":false,"description":"用 rcm 管理隐藏文件 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 rcm 管理隐藏文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 rcm 管理隐藏文件 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20190104 Managing dotfiles with rcm","title":"用 rcm 管理隐藏文件","tag":"201901","desc":""},"relativePath":"201901/20190104 Managing dotfiles with rcm.md","filePath":"[post].md"}'),c={name:"201901/20190104 Managing dotfiles with rcm.md"};function h(g,s,k,m,u,b){const a=p("Link");return o(),r("div",null,[s[24]||(s[24]=i("h1",{id:"用-rcm-管理隐藏文件",tabindex:"-1"},[n("用 rcm 管理隐藏文件 "),i("a",{class:"header-anchor",href:"#用-rcm-管理隐藏文件","aria-label":"Permalink to “用 rcm 管理隐藏文件”"},"​")],-1)),s[25]||(s[25]=i("p",null,[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/12/dotfiles-816x345.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=n("许多 GNU/Linux 程序的一个特点是有个易于编辑的配置文件。几乎所有常见的自由软件都将配置设置保存在纯文本文件中，通常采用结构化格式，如 JSON、YAML 或",-1)),l(a,{href:"https://en.wikipedia.org/wiki/INI_file"},{default:e(()=>[...s[0]||(s[0]=[n("“类似 ini”",-1)])]),_:1}),s[2]||(s[2]=n(" 的文件中。这些配置文件经常隐藏在用户的主目录中。但是，基本的 ",-1)),s[3]||(s[3]=i("code",null,"ls",-1)),s[4]||(s[4]=n(" 不会显示它们。UNIX 标准要求以点开头的任何文件或目录名称都被视为“隐藏”，除非用户特意要求，否则不会列在目录列表中。例如，要使用 ",-1)),s[5]||(s[5]=i("code",null,"ls",-1)),s[6]||(s[6]=n(" 列出所有文件，要传递 ",-1)),s[7]||(s[7]=i("code",null,"-a",-1)),s[8]||(s[8]=n(" 选项。",-1))]),s[26]||(s[26]=d(`<p>随着时间的推移，这些配置文件会有很多定制配置，管理它们变得越来越具有挑战性。不仅如此，在多台计算机之间保持同步是大型组织所面临的共同挑战。最后，许多用户也对其独特的配置感到自豪，并希望以简单的方式与朋友分享。这就是用到 rcm 介入的地方。</p><p>rcm 是一个 “rc” 文件管理套件（“rc” 是命名配置文件的另一种约定，它已被某些 GNU/Linux 程序采用，如 <code>screen</code> 或 <code>bash</code>）。 rcm 提供了一套命令来管理和列出它跟踪的文件。使用 <code>dnf</code> 安装 rcm。</p><h3 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to “开始使用”">​</a></h3><p>默认情况下，rcm 使用 <code>~/.dotfiles</code> 来存储它管理的所有隐藏文件。一个被管理的隐藏文件实际保存在 <code>~/.dotfiles</code> 目录中，而它的符号链接会放在文件原本的位置。例如，如果 <code>~/.bashrc</code> 由 rcm 所管理，那么详细列表将如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@localhost ~]$ ls -l ~/.bashrc</span></span>
<span class="line"><span>lrwxrwxrwx. 1 link link 27 Dec 16 05:19 .bashrc -&gt; /home/link/.dotfiles/bashrc</span></span>
<span class="line"><span>[link@localhost ~]$</span></span></code></pre></div><p>rcm 包含 4 个命令：</p><ul><li><code>mkrc</code> – 将文件转换为由 rcm 管理的隐藏文件</li><li><code>lsrc</code> – 列出由 rcm 管理的文件</li><li><code>rcup</code> – 同步由 rcm 管理的隐藏文件</li><li><code>rcdn</code> – 删除 rcm 管理的所有符号链接</li></ul><h3 id="在两台计算机上共享-bashrc" tabindex="-1">在两台计算机上共享 bashrc <a class="header-anchor" href="#在两台计算机上共享-bashrc" aria-label="Permalink to “在两台计算机上共享 bashrc”">​</a></h3><p>如今用户在多台计算机上拥有 shell 帐户并不罕见。在这些计算机之间同步隐藏文件可能是一个挑战。这里将提供一种可能的解决方案，仅使用 rcm 和 git。</p><p>首先使用 <code>mkrc</code> 将文件转换成由 rcm 管理的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@localhost ~]$ mkrc -v ~/.bashrc</span></span>
<span class="line"><span>Moving...</span></span>
<span class="line"><span>&#39;/home/link/.bashrc&#39; -&gt; &#39;/home/link/.dotfiles/bashrc&#39;</span></span>
<span class="line"><span>Linking...</span></span>
<span class="line"><span>&#39;/home/link/.dotfiles/bashrc&#39; -&gt; &#39;/home/link/.bashrc&#39;</span></span>
<span class="line"><span>[link@localhost ~]$</span></span></code></pre></div><p>接下来使用 <code>lsrc</code> 验证列表是否正确。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@localhost ~]$ lsrc</span></span>
<span class="line"><span>/home/link/.bashrc:/home/link/.dotfiles/bashrc</span></span>
<span class="line"><span>[link@localhost ~]$</span></span></code></pre></div><p>现在在 <code>~/.dotfiles</code> 中创建一个 git 仓库，并使用你选择的 git 仓库托管设置一个远程仓库。提交 <code>bashrc</code> 文件并推送一个新分支。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@localhost ~]$ cd ~/.dotfiles</span></span>
<span class="line"><span>[link@localhost .dotfiles]$ git init</span></span>
<span class="line"><span>Initialized empty Git repository in /home/link/.dotfiles/.git/</span></span>
<span class="line"><span>[link@localhost .dotfiles]$ git remote add origin git@github.com:linkdupont/dotfiles.git</span></span>
<span class="line"><span>[link@localhost .dotfiles]$ git add bashrc</span></span>
<span class="line"><span>[link@localhost .dotfiles]$ git commit -m &quot;initial commit&quot;</span></span>
<span class="line"><span>[master (root-commit) b54406b] initial commit</span></span>
<span class="line"><span>1 file changed, 15 insertions(+)</span></span>
<span class="line"><span>create mode 100644 bashrc</span></span>
<span class="line"><span>[link@localhost .dotfiles]$ git push -u origin master</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[link@localhost .dotfiles]$</span></span></code></pre></div><p>在第二台机器上，克隆这个仓库到 <code>~/.dotfiles</code> 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@remotehost ~]$ git clone git@github.com:linkdupont/dotfiles.git ~/.dotfiles</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[link@remotehost ~]$</span></span></code></pre></div><p>现在使用 <code>rcup</code> 更新受 rcm 管理的符号链接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@remotehost ~]$ rcup -v</span></span>
<span class="line"><span>replacing identical but unlinked /home/link/.bashrc</span></span>
<span class="line"><span>removed &#39;/home/link/.bashrc&#39;</span></span>
<span class="line"><span>&#39;/home/link/.dotfiles/bashrc&#39; -&gt; &#39;/home/link/.bashrc&#39;</span></span>
<span class="line"><span>[link@remotehost ~]$</span></span></code></pre></div><p>覆盖现有的 <code>~/.bashrc</code>（如果存在）并重启 shell。</p><p>就是这些了！指定主机选项 （<code>-o</code>） 是对上面这种情况的有用补充。如往常一样，请阅读手册页。它们包含了很多示例命令。</p><hr>`,22)),i("p",null,[s[10]||(s[10]=n("via: ",-1)),l(a,{href:"https://fedoramagazine.org/managing-dotfiles-rcm/"},{default:e(()=>[...s[9]||(s[9]=[n("https://fedoramagazine.org/managing-dotfiles-rcm/",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=n("作者：",-1)),l(a,{href:"https://fedoramagazine.org/author/linkdupont/"},{default:e(()=>[...s[11]||(s[11]=[n("Link Dupont",-1)])]),_:1}),s[16]||(s[16]=n(" 选题：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[12]||(s[12]=[n("lujun9972",-1)])]),_:1}),s[17]||(s[17]=n(" 译者：",-1)),l(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[13]||(s[13]=[n("geekpi",-1)])]),_:1}),s[18]||(s[18]=n(" 校对：",-1)),l(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[14]||(s[14]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[21]||(s[21]=n("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原创编译，",-1)),l(a,{href:"https://linux.cn/"},{default:e(()=>[...s[20]||(s[20]=[n("Linux中国",-1)])]),_:1}),s[23]||(s[23]=n(" 荣誉推出",-1))])])}const T=t(c,[["render",h]]);export{C as __pageData,T as default};
